// Delivers the application itself — but only to a signed-in user. Before login the
// browser receives just a small login page (index.html); the real app code never
// sits in a public file. The code is stored (obfuscated + gzipped) in _app.js.

import { verifySession } from "./_auth.js";
// The packed application (gzip + base64) is kept inside this file so the function has no extra module to resolve.
const APP_GZ_B64 = "";

// v183: notifications queue one after another, repeating cloud-retry notices appear once a minute, typing is never interrupted (see CHANGES-v183.md)
// v178: much faster Dashboard/Marks Report (subject levels read once instead of ~31,000 times); Dashboard is not drawn before sign-in (see CHANGES-v178.md)
// v177: the "Could not reach cloud database" line now shows the reason; first load waits up to 30 s (was 12 s) (see CHANGES-v177.md)
// v176: slow-save notice shows how long the save took and how much was server time (see CHANGES-v176.md)
// v175: faster teacher mark saving - fewer database round trips, one lookup instead of one per student, 45 s allowance for writes (see CHANGES-v175.md)
// v174: Students tab "Fix class names" (S1 A -> S1A) + import removes spaces in class (see CHANGES-v174.md)
// v168: login page honors a one-use resume marker so report-card refresh returns to the active tab without a PIN (see CHANGES-v168.md)
// v167: post-download refresh preserves the one-time signed-in session and reopens the Report Cards tab (see CHANGES-v167.md)
// v166: bulk report-card PDF generation shows percent progress and refreshes after the browser save is triggered (see CHANGES-v166.md)
// v165: bulk class report-card PDF pages are ordered by calculated position, first to last (see CHANGES-v165.md)
// v164: missing student marks count as 0 across every mark-based average/position; non-applicable subjects stay excluded (see CHANGES-v164.md)
// v163: missing mark = 0 also in Individual Analysis, risk counts, progress charts, report-card month averages (see CHANGES-v163.md)
// v162: missing mark = 0 in every report average; equal averages share the same position (see CHANGES-v162.md)
// v161: Marks Report average counts a missing mark as 0 (see CHANGES-v161.md)
// v160: One PIN per teacher: Sync to Cloud keeps teachers' current PINs, no second teacher with the same name, same-name duplicates lose their PIN when the teacher changes his (see CHANGES-v160.md)
// v154: Change My PIN needs exactly 6 digits (see CHANGES-v154.md)
// v153: Teachers can change their own PIN (menu "Change My PIN" + new api/change-pin.js, see CHANGES-v153.md)
// v152: Marks submitted from Enter Marks are also listed in Saved Marks as Submitted (see CHANGES-v152.md)
// v151: Submitted rows in Saved Marks follow later edits in the database (see CHANGES-v151.md)
// v150: Saved Marks page, Submit button, Summary Report under Assessment Management (see CHANGES-v150.md)
// v148: Mark Scale Converter page (see CHANGES-v148.md)
// v111: faster start (see CHANGES-v111.md)
// v109: run next to the Turso database (change "fra1" if your Turso DB is in another region)
export const config = { runtime: "edge", regions: ["fra1"] };

let cachedBytes = null;
function appBytes() {
  if (!cachedBytes) cachedBytes = Uint8Array.from(atob(APP_GZ_B64), (c) => c.charCodeAt(0));
  return cachedBytes;
}

export default async function handler(request) {
  const noStore = { "Cache-Control": "no-store, private", "X-Robots-Tag": "noindex, nofollow" };
  if (request.method !== "GET") return new Response("Method not allowed", { status: 405, headers: noStore });
  const session = await verifySession(request);
  if (!session) return new Response(JSON.stringify({ error: "Please sign in." }), { status: 401, headers: { "Content-Type": "application/json", ...noStore } });
  // v110: return decoded HTML. Let Vercel manage transport compression so
  // browsers never receive raw gzip bytes after intermediary header changes.
  const stream = new Blob([appBytes()]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream, { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", ...noStore } });
}
